tool_input.command:
node --input-type=module -e "
import { handle, toUtcMs } from './src/api.js';
import { dueReminders } from './src/scheduler.js';
import { queryLog } from './src/db.js';
const c = (b) => handle({ method: 'POST', path: '/reminders', body: b });
console.log('seconds:', c({ userId:'u1', text:'a', at:'2026-03-01T09:00:00' }));
console.log('Z suffix:', c({ userId:'u1', text:'a', at:'2026-03-01T09:00Z' }).body.due_ms);
console.log('garbage:', c({ userId:'u1', text:'a', at:'tomorrow' }).status);
const r = c({ userId:'u1', text:'call mum', at:'2026-03-01T09:00', tzOffsetMin: 330 }).body;
console.log('IST due_ms', new Date(r.due_ms).toISOString());
for (const t of ['2026-02-28T22:00:00Z','2026-03-01T03:30:00Z']) console.log('due at', t, dueReminders([r], Date.parse(t)).length);
try { console.log(handle({ method:'GET', path:'/reminders/search', query:{ userId:'u1', q:'milk and eggs' } })); } catch (e) { console.log('search threw:', e.message); }
handle({ method:'GET', path:'/reminders/search', query:{ userId:\"x' OR '1'='1\", q:'' } });
console.log('sql:', queryLog.at(-1).sql);
try { handle({ method:'GET', path:'/reminders' }); } catch (e) { console.log('list no query threw:', e.message); }
"
